int load_segment_descriptor(struct x86_emulate_ctxt *ctxt, u16 selector, int seg, u8 cpl, bool in_task_switch, struct desc_struct *desc) {
    u16 ti, rpl, index;
    struct desc_struct *d;

    ti = (selector >> 2) & 1;
    rpl = selector & 3;
    index = selector >> 3;

    if (ctxt->mode == X86EMUL_MODE_REAL || ctxt->mode == X86EMUL_MODE_VM86) {
        d = get_real_mode_descriptor(ctxt, selector);
        if (!d)
            return real_mode_invalid_selector(ctxt, seg);

        desc_write(desc, d);
        return X86EMUL_CONTINUE;
    }

    if (!index && !ctxt->ldt_base) {
        return X86EMUL_UNHANDLEABLE;
    }

    if (seg == VCPU_SREG_CS || seg == VCPU_SREG_SS) {
        if (rpl > cpl)
            return X86EMUL_UNHANDLEABLE;
    }

    d = get_descriptor(ctxt, index, ti, seg);
    if (!d)
        return X86EMUL_UNHANDLEABLE;

    desc_write(desc, d);
    set_segment(ctxt, seg, selector, d);

    return X86EMUL_CONTINUE;
}

int load_segment_descriptor(struct x86_emulate_ctxt *ctxt, u16 selector, int seg, u8 cpl, bool in_task_switch, struct desc_struct *desc) {
    struct desc_struct *d = &ctxt->desc[seg];
    int type;

    if ((selector & 0xfffc) == 0) {
        if (seg == VCPU_SREG_CS) {
            return real_mode_write_exception(ctxt);
        } else {
            d->bits.base = 0;
            d->bits.limit = 0;
            d->bits.type = 0;
            d->bits.present = 0;
            d->bits.segment = 1;
            d->bits.db = 0;
            d->bits.s = 1;
            d->bits.g = 0;
            d->bits.avl = 0;
            d->bits.p = 0;
            d->bits.dpl = 0;
            d->bits.l = 0;
            d->bits.unused = 0;
            d->bits.base_high = 0;
            ctxt->segment[seg] = selector;
            if (desc)
                *desc = *d;
            return X86EMUL_CONTINUE;
        }
    }

    if ((ctxt->mode == X86EMUL_MODE_REAL) || (ctxt->mode == X86EMUL_MODE_VM86)) {
        d->bits.base = selector << 4;
        d->bits.limit = 0xffff;
        d->bits.type = 3;
        d->bits.present = 1;
        d->bits.segment = 1;
        d->bits.db = 0;
        d->bits.s = 1;
        d->bits.g = 0;
        d->bits.avl = 0;
        d->bits.p = 0;
        d->bits.dpl = 0;
        d->bits.l = 0;
        d->bits.unused = 0;
        d->bits.base_high = 0;
        ctxt->segment[seg] = selector;
        if (desc)
            *desc = *d;
        return X86EMUL_CONTINUE;
    }

    if ((selector & 0x0007) != 3) {
        if (seg == VCPU_SREG_CS) {
            type = ((selector >> 4) & 0x000f);
            if (type != 0x0b && type != 0x03)
                return general_protection(ctxt, 0);

            if ((type == 0x0b) && (ctxt->mode != X86EMUL_MODE_PROT64))
                return general_protection(ctxt, 0);

            if ((type == 0x03) && (ctxt->mode != X86EMUL_MODE_PROT32))
                return general_protection(ctxt, 0);

            if (selector & 0x0010)
                d->bits.l = 1;
            else
                d->bits.l = 0;

            d->bits.base = 0;
            d->bits.limit = 0xfffff;
            d->bits.type = type;
            d->bits.present = 1;
            d->bits.segment = 0;
            d->bits.db = 0;
            d->bits.s = 1;
            d->bits.g = 1;
            d->bits.avl = 0;
            d->bits.p = 0;
            d->bits.dpl = (selector >> 5) & 0x0003;
            d->bits.unused = 0;
            d->bits.base_high = 0;
        } else if (seg == VCPU_SREG_SS) {
            type = ((selector >> 4) & 0x000f);
            if (type != 0x03)
                return general_protection(ctxt, 0);

            d->bits.base = 0;
            d->bits.limit = 0xfffff;
            d->bits.type = type;
            d->bits.present = 1;
            d->bits.segment = 0;
            d->bits.db = 0;
            d->bits.s = 1;
            d->bits.g = 1;
            d->bits.avl = 0;
            d->bits.p = 0;
            d->bits.dpl = (selector >> 5) & 0x0003;
            d->bits.unused = 0;
            d->bits.base_high = 0;
        } else {
            type = ((selector >> 4) & 0x000f);
            if ((type != 0x01) && (type != 0x09))
                return general_protection(ctxt, 0);

            d->bits.base = 0;
            d->bits.limit = 0xfffff;
            d->bits.type = type;
            d->bits.present = 1;
            d->bits.segment = 0;
            d->bits.db = 0;
            d->bits.s = 1;
            d->bits.g = 1;
            d->bits.avl = 0;
            d->bits.p = 0;
            d->bits.dpl = (selector >> 5) & 0x0003;
            d->bits.unused = 0;
            d->bits.base_high = 0;
        }

        ctxt->segment[seg] = selector;
        if (desc)
            *desc = *d;
        return X86EMUL_CONTINUE;
    }

    return general_protection(ctxt, 0);
}

int load_segment_descriptor(struct x86_emulate_ctxt *ctxt, u16 selector, int seg, u8 cpl, bool in_task_switch, struct desc_struct *desc) {
    union {
        struct {
            unsigned int limit;
            unsigned long base;
        };
        struct desc_struct *desc;
    } res;
    unsigned int type, dpl;
    bool is_kernel = ((selector & SEGMENT_RPL_MASK) < cpl);

    if ((selector & SEGMENT_TI_MASK) && !in_task_switch) {
        return REAL_EXCEPTION_VECTOR(DESC_FAULT);
    }

    if (!selector) {
        if (seg == VMENTER_CPL)
            return REAL_EXCEPTION_VECTOR(GENERAL_PROTECTION);
        res.base = 0;
        res.limit = 0;
        if (seg == VMENTER_CS) {
            res.base = 0;
            res.limit = 0xffff;
        }
        if (desc)
            *desc = *(struct desc_struct *)&res;
        ctxt->regs[seg] = (selector & 0xfffc) | (is_kernel ? 0 : 1);
        return X86EMUL_CONTINUE;
    }

    if (ctxt->mode == X86EMUL_MODE_REAL || ctxt->mode == X86EMUL_MODE_VM86) {
        res.base = selector << 4;
        res.limit = 0xffff;
        if (desc)
            *desc = *(struct desc_struct *)&res;
        ctxt->regs[seg] = selector;
        return X86EMUL_CONTINUE;
    }

    if (ctxt->mode == X86EMUL_MODE_PROT) {
        if (ctxt->ldt.base && (selector & SEGMENT_TI_MASK))
            res.desc = (struct desc_struct *)((ctxt->ldt.base) + (selector & 0xfffc));
        else
            res.desc = (struct desc_struct *)((ctxt->gdt.base) + (selector & 0xfffc));

        if ((res.desc->limit & 0xffff) > ctxt->gdt.limit)
            return REAL_EXCEPTION_VECTOR(BOUND_CHECK);

        type = (res.desc->type & 0x1f);
        dpl = (res.desc->dpl & 0x3);

        if ((type & 0x10) && seg != VMENTER_CS)
            return REAL_EXCEPTION_VECTOR(GENERAL_PROTECTION);

        if ((type & 0x4) && seg != VMENTER_SS)
            return REAL_EXCEPTION_VECTOR(GENERAL_PROTECTION);

        if ((type & 0x8) && seg != VMENTER_TR)
            return REAL_EXCEPTION_VECTOR(GENERAL_PROTECTION);

        if ((dpl < cpl) && (type & 0x4))
            return REAL_EXCEPTION_VECTOR(GENERAL_PROTECTION);

        if (desc)
            *desc = *res.desc;
        ctxt->regs[seg] = (selector & 0xfffc) | (is_kernel ? 0 : 1);
        return X86EMUL_CONTINUE;
    }

    return REAL_EXCEPTION_VECTOR(INTERNAL_ERROR);
}

int load_segment_descriptor(struct x86_emulate_ctxt *ctxt, u16 selector, int seg, u8 cpl, bool in_task_switch, struct desc_struct *desc) {
    struct desc_struct *d = &ctxt->segment_descriptor[seg];
    u16 ti, rpl;
    int prot_mode = ctxt->mode != X86EMUL_MODE_REAL && !ctxt->in_vm86;

    ti = (selector >> 2) & 3;
    rpl = selector & 3;

    if (!prot_mode && (seg == VMENTRY_SEG_CS || seg == VMENTRY_SEG_SS)) {
        if (selector & 0xff00)
            return X86EMUL_UNHANDLEABLE;

        d->limit = selector << 4;
        d->base = 0;
        d->type = 0;
        d->s = 1;
        d->dpl = 0;
        d->p = 1;
        d->avl = 0;
        d->l = 0;
        d->db = 0;
        d->g = 0;
    } else {
        if (!ctxt->mode && seg == VMENTRY_SEG_CS) {
            if (selector != 0)
                return X86EMUL_UNHANDLEABLE;
            d->limit = 0xffff;
            d->base = 0;
            d->type = 0;
            d->s = 1;
            d->dpl = 0;
            d->p = 1;
            d->avl = 0;
            d->l = 0;
            d->db = 1;
            d->g = 1;
        } else {
            if (selector == 0) {
                d->limit = 0;
                d->base = 0;
                d->type = 0;
                d->s = 0;
                d->dpl = 0;
                d->p = 0;
                d->avl = 0;
                d->l = 0;
                d->db = 0;
                d->g = 0;
            } else {
                if (seg == VMENTRY_SEG_CS || seg == VMENTRY_SEG_SS) {
                    if (rpl > cpl)
                        return X86EMUL_UNHANDLEABLE;
                    if (seg == VMENTRY_SEG_CS && (ctxt->mode == X86EMUL_MODE_PROT || ctxt->mode == X86EMUL_MODE_PROT32)) {
                        if (d->type != 0x9 && d->type != 0xB)
                            return X86EMUL_UNHANDLEABLE;
                    }
                }
                d->limit = 0xffff;
                d->base = 0;
                d->type = 0x1;
                d->s = 1;
                d->dpl = rpl;
                d->p = 1;
                d->avl = 0;
                d->l = 0;
                d->db = 1;
                d->g = 1;
            }
        }
    }

    if (desc)
        *desc = *d;

    return X86EMUL_CONTINUE;
}

int load_segment_descriptor(struct x86_emulate_ctxt *ctxt, u16 selector, int seg, u8 cpl, bool in_task_switch, struct desc_struct *desc) {
    struct desc_struct *d = NULL;
    u16 ti, rpl, index;
    int rc = X86EMUL_CONTINUE;

    ti = (selector >> 2) & 1;
    rpl = selector & 3;
    index = selector >> 3;

    if (ctxt->mode == X86EMUL_MODE_REAL) {
        if (seg == VMENTER_SEL_CS) {
            d = &ctxt->real_mode_gdt[index];
        } else {
            return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
        }
    } else if (ctxt->mode == X86EMUL_MODE_VM86) {
        if (seg == VMENTER_SEL_CS) {
            d = &ctxt->vm86_gdt[index];
        } else {
            return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
        }
    } else {
        if (!index && !ti) {
            switch (seg) {
                case VMENTER_SEL_CS:
                case VMENTER_SEL_SS:
                case VMENTER_SEL_DS:
                case VMENTER_SEL_ES:
                case VMENTER_SEL_FS:
                case VMENTER_SEL_GS:
                    d = &ctxt->idt[index];
                    break;
                case VMENTER_SEL_TR:
                    d = &ctxt->tr;
                    break;
                default:
                    return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
            }
        } else {
            return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
        }
    }

    if (!d) {
        return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
    }

    if (seg == VMENTER_SEL_SS || seg == VMENTER_SEL_TR) {
        if (cpl > rpl) {
            return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
        }
    }

    if (desc) {
        *desc = *d;
    }

    ctxt->regs[seg] = selector;
    return rc;
}
